import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { App } from 'aws-cdk-lib';
import { createStack } from './product.mjs';

// Trusted, private native Node preview. It synthesizes the actual product stack
// locally and returns only bounded counts; no CloudFormation template or AWS
// API call leaves this module. The gateway Worker currently cannot execute it.
export async function preview({ configuration, selected_components }) {
  let outdir;
  try {
    if (!Array.isArray(selected_components) || selected_components.length !== 1 || selected_components[0] !== 'stack') {
      return { ok: false, status: 'invalid', slug: 'bedrock-guardrails-cdk', selected_components: [], resource_count: 0, diagnostic_codes: ['invalid_selection'] };
    }
    if (!configuration || configuration.language !== 'javascript') {
      return { ok: false, status: 'invalid', slug: 'bedrock-guardrails-cdk', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['configuration_invalid'] };
    }
    outdir = mkdtempSync(join(tmpdir(), 'secondwind-private-cdk-preview-'));
    const app = new App({ outdir, analyticsReporting: false });
    createStack(app, { configuration, selected_components });
    const assembly = app.synth();
    const resource_count = assembly.stacks.reduce((sum, stack) => sum + Object.keys(stack.template?.Resources || {}).length, 0);
    return { ok: true, status: 'complete', slug: 'bedrock-guardrails-cdk', selected_components: ['stack'], resource_count };
  } catch {
    return { ok: false, status: 'invalid', slug: 'bedrock-guardrails-cdk', selected_components: ['stack'], resource_count: 0, diagnostic_codes: ['validation_failed'] };
  } finally {
    if (outdir) rmSync(outdir, { recursive: true, force: true });
  }
}

import { App, Stack } from 'aws-cdk-lib';
import { Guardrail, ContentFilterStrength, ContentFilterType, GuardrailAction } from '@cdklabs/generative-ai-cdk-constructs/lib/cdk-lib/bedrock/index.js';

export function createStack(app, { configuration: c }) {
  if (!c || typeof c.guardrail_name !== 'string' || !Array.isArray(c.categories) || !c.categories.length) {
    throw new Error('invalid_configuration');
  }
  const allowed = new Set(Object.values(ContentFilterType));
  if (c.categories.some((entry) => !allowed.has(entry.type) || !['LOW', 'MEDIUM', 'HIGH'].includes(entry.strength))) {
    throw new Error('invalid_filter');
  }
  const stack = new Stack(app, 'BedrockGuardrailStack');
  new Guardrail(stack, 'Guardrail', {
    name: c.guardrail_name,
    description: c.description,
    blockedInputMessaging: c.blocked_input_message,
    blockedOutputsMessaging: c.blocked_output_message,
    contentFilters: c.categories.map(({ type, strength }) => ({
      type,
      inputStrength: ContentFilterStrength[strength],
      outputStrength: ContentFilterStrength[strength],
      inputAction: GuardrailAction.BLOCK,
      outputAction: GuardrailAction.BLOCK,
    })),
  });
  return stack;
}

export function synthesize(configuration) {
  const app = new App({ analyticsReporting: false });
  createStack(app, { configuration });
  return app.synth();
}

